import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, ListRenderItem } from 'react-native'
import { useContexState } from '../../hooks/context';

import Axios from 'axios';
import { Cards } from '../../components/Cards';
import { styles } from './styles';

interface listProps {
    data: {
        title: string,
        key: string
    }[];
    list?: {
        ['number']: {
            id: number;
            name: string;
            phone: string;
            price: number;
        }
    }[];
}

export function ListItem(props: listProps) {
    return (
        <View style={styles.listItem}>
            <Cards listItemProps={props} position={0} />
            <Cards listItemProps={props} position={1} />
            <Cards listItemProps={props} position={2} />
            <Cards listItemProps={props} position={3} />
            <Cards listItemProps={props} position={4} />
            <Cards listItemProps={props} position={5} />
        </View>
    );
};
